#!/usr/bin/env python3
# ⏳🤖 Generated by an LLM, pending human review.
"""Read-only w43 sync smoke through an existing local relay, with a new scratch DB."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import signal
import subprocess
import time


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--node", required=True, type=Path)
    p.add_argument("--cli", required=True, type=Path)
    p.add_argument("--config", required=True, type=Path)
    p.add_argument("--root", required=True, type=Path)
    p.add_argument("--peer-port", type=int, default=3010)
    p.add_argument("--port", type=int, default=34611)
    a = p.parse_args()
    assert a.port != a.peer_port
    root = a.root.resolve()
    root.mkdir(parents=True, exist_ok=False)
    config = json.loads(a.config.read_text())
    for key, value in list(config.items()):
        if key.endswith("GenesisFile"):
            config[key] = str((a.config.parent / value).resolve())
    genesis_bytes = Path(config["ShelleyGenesisFile"]).read_bytes()
    genesis = json.loads(genesis_bytes)
    assert genesis["networkMagic"] == 164
    assert genesis["systemStart"] == "2026-10-18T00:00:00Z"
    assert hashlib.sha256(genesis_bytes).hexdigest() == "0c7365b3e74a52a09d1ad169438b714919dd36710c9feed8e49be65e73990ab7"
    config["TraceOptions"] = {"": {"severity": "Info", "detail": "DNormal", "backends": ["Stdout MachineFormat"]}}
    config["PeerSharing"] = False
    config["TraceOptionTransactions"] = dict(fullTxIds=True, suppressTxBodies=True)
    config["TraceOptionTransactionIdentity"] = dict(includeMempoolIdentityPairs=True)
    config["TraceOptionLeios"] = dict(includeTxReferences=True)
    (root / "config.json").write_text(json.dumps(config))
    (root / "topology.json").write_text(json.dumps(dict(
        localRoots=[dict(accessPoints=[dict(address="127.0.0.1", port=a.peer_port)],
                         advertise=False, valency=1, trustable=True)],
        publicRoots=[], useLedgerAfterSlot=-1, bootstrapPeers=None)))
    args = [str(a.node), "run", "--config", str(root / "config.json"), "--topology", str(root / "topology.json"),
            "--database-path", str(root / "db"), "--socket-path", str(root / "node.socket"),
            "--host-addr", "127.0.0.1", "--port", str(a.port), "--suppress-inbound-tx-submission",
            "+RTS", "-N2", "-RTS"]
    env = {k: v for k, v in os.environ.items() if not k.startswith("CARDANO_NODE_")}
    begin = time.monotonic()
    result = dict(argv=args, magic=164, system_start=genesis["systemStart"],
                  version=subprocess.check_output([str(a.node), "--version"], text=True),
                  genesis_sha256=hashlib.sha256(genesis_bytes).hexdigest(), observations=[])
    with (root / "node.log").open("w") as log:
        process = subprocess.Popen(args, env=env, stdout=log, stderr=subprocess.STDOUT)
        try:
            while time.monotonic() - begin < 90:
                assert process.poll() is None, "standalone node exited during startup"
                if (root / "node.socket").is_socket():
                    query = subprocess.run([str(a.cli), "dijkstra", "query", "tip", "--testnet-magic", "164",
                                            "--socket-path", str(root / "node.socket")], env=env,
                                           text=True, capture_output=True, timeout=10)
                    observation = dict(returncode=query.returncode, stdout=query.stdout, stderr=query.stderr)
                    result["observations"].append(observation)
                    if query.returncode == 0 and json.loads(query.stdout).get("block", 0) >= 5:
                        result["tip"] = json.loads(query.stdout)
                        break
                time.sleep(0.5)
            else:
                raise TimeoutError("standalone node did not sync five blocks")
            result["memory"] = [line for line in Path(f"/proc/{process.pid}/status").read_text().splitlines()
                                if line.startswith(("VmHWM:", "VmRSS:"))]
        finally:
            if process.poll() is None:
                process.send_signal(signal.SIGTERM)
            try:
                process.wait(timeout=20)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait(timeout=5)
                raise RuntimeError("standalone node did not stop cleanly")
            result["returncode"] = process.returncode
            result["elapsed_seconds"] = time.monotonic() - begin
            (root / "result.json").write_text(json.dumps(result, indent=2) + "\n")
        assert process.returncode == 0
    result["status"] = "PASS"
    (root / "result.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
